import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, nowIso } from './db.ts';

const db = openDatabase();
let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) process.on(signal, () => { stopping = true; });

// Any running row belongs to a worker that is no longer processing it. Put it back
// in the durable queue; the next claim starts a fresh attempt.
db.prepare("UPDATE jobs SET status='queued', progress_completed=0, updated_at=?, available_at=0 WHERE status='running'").run(nowIso());
const heartbeat = () => db.prepare(`INSERT INTO worker_heartbeat(singleton,at) VALUES(1,?)
  ON CONFLICT(singleton) DO UPDATE SET at=excluded.at`).run(Date.now());
heartbeat();
const heartbeatTimer = setInterval(heartbeat, 500);

async function claim(): Promise<{ id: string; input: string; steps: number; failAttempts: number; attempts: number } | undefined> {
  db.exec('BEGIN IMMEDIATE');
  try {
    const row = db.prepare("SELECT id,input,steps,fail_attempts,attempts FROM jobs WHERE status='queued' AND available_at<=? ORDER BY created_at ASC,rowid ASC LIMIT 1").get(Date.now()) as {
      id: string; input: string; steps: number; fail_attempts: number; attempts: number;
    } | undefined;
    if (!row) { db.exec('COMMIT'); return undefined; }
    const attempts = Number(row.attempts) + 1;
    db.prepare("UPDATE jobs SET status='running',attempts=?,progress_completed=0,result=NULL,error=NULL,updated_at=? WHERE id=? AND status='queued'").run(attempts, nowIso(), row.id);
    db.exec('COMMIT');
    return { id: row.id, input: row.input, steps: Number(row.steps), failAttempts: Number(row.fail_attempts), attempts };
  } catch (error) { db.exec('ROLLBACK'); throw error; }
}

async function processJob(job: { id: string; input: string; steps: number; failAttempts: number; attempts: number }): Promise<void> {
  for (let completed = 1; completed <= job.steps; completed++) {
    await sleep(100);
    if (completed === 1 && job.attempts <= job.failAttempts) {
      const timestamp = nowIso();
      if (job.attempts >= 3) {
        db.prepare("UPDATE jobs SET status='failed',progress_completed=0,error='transient failure',result=NULL,updated_at=? WHERE id=? AND status='running'").run(timestamp, job.id);
      } else {
        db.prepare("UPDATE jobs SET status='queued',progress_completed=0,error=NULL,result=NULL,available_at=?,updated_at=? WHERE id=? AND status='running'").run(Date.now() + 500, timestamp, job.id);
      }
      return;
    }
    db.prepare("UPDATE jobs SET progress_completed=?,updated_at=? WHERE id=? AND status='running'").run(completed, nowIso(), job.id);
  }
  db.prepare("UPDATE jobs SET status='completed',progress_completed=?,result=?,error=NULL,updated_at=? WHERE id=? AND status='running'")
    .run(job.steps, JSON.stringify({ output: job.input.toUpperCase() }), nowIso(), job.id);
}

console.log('worker started');
try {
  while (!stopping) {
    heartbeat();
    const job = await claim();
    if (!job) { await sleep(100); continue; }
    await processJob(job);
  }
} finally {
  clearInterval(heartbeatTimer);
  db.prepare('DELETE FROM worker_heartbeat WHERE singleton=1').run();
  db.close();
}
import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
