      if (key !== undefined) {
        const prior = db.prepare('SELECT i.payload, j.* FROM idempotency i JOIN jobs j ON j.id=i.job_id WHERE i.key=?').get(key) as (Record<string, unknown> & { payload: string }) | undefined;
        if (prior) {
          db.exec('COMMIT');
          if (prior.payload !== payload) apiError(res, 409, 'idempotency_conflict', 'This key was already used with a different payload.');
          else send(res, 200, toJob(prior));
          return;
        }
      }
      db.prepare(`INSERT INTO jobs(id,status,input,steps,fail_attempts,attempts,progress_completed,created_at,updated_at,available_at)
        VALUES(?, 'queued', ?, ?, ?, 0, 0, ?, ?, 0)`).run(id, input as string, steps as number, failAttempts as number, timestamp, timestamp);
      if (key !== undefined) db.prepare('INSERT INTO idempotency(key,payload,job_id) VALUES(?,?,?)').run(key, payload, id);
      db.exec('COMMIT');
    } catch (error) { db.exec('ROLLBACK'); throw error; }
    const row = db.prepare('SELECT * FROM jobs WHERE id=?').get(id) as Record<string, unknown>;
    send(res, 201, toJob(row)); return;
  }
  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match && req.method === 'GET') {
    let id: string; try { id = decodeURIComponent(match[1]!); } catch { apiError(res, 404, 'not_found', 'Job not found.'); return; }
    const row = db.prepare('SELECT * FROM jobs WHERE id=?').get(id) as Record<string, unknown> | undefined;
    if (!row) apiError(res, 404, 'not_found', 'Job not found.'); else send(res, 200, toJob(row));
    return;
  }
  const known = pathname === '/' || pathname === '/health' || pathname === '/api/jobs' || /^\/api\/jobs\/[^/]+$/.test(pathname);
  apiError(res, known ? 405 : 404, known ? 'method_not_allowed' : 'not_found', known ? 'Method not allowed.' : 'Route not found.');
});

const port = Number(process.env.PORT ?? 3000);
server.listen(port, () => console.log(`server listening on ${port}`));
for (const signal of ['SIGINT', 'SIGTERM'] as const) process.on(signal, () => server.close(() => { db.close(); process.exit(0); }));

